import { useState } from 'react'
import { Box, Button, Loader, Stack, Text, Tooltip } from '@mantine/core'
import DetailPanel from '../DetailPanel'
import Toolbar from '../Toolbar'
import TruncatedText from '../TruncatedText'
import DriveFolderPickerModal from './components/DriveFolderPickerModal'
import DriveThumbnailPanel from './components/ThumbnailPanel'
import GroupNode from './components/GroupNode'
import FileList from './components/FileList'
import ResizableLeftPanel from './components/ResizableLeftPanel'
import UploadModal from './components/UploadModal'
import { useFileTree } from './hooks/useFileTree'
import { useDriveAssignments } from './hooks/useDriveAssignments'
import { useInclusion } from './hooks/useInclusion'
import { useSelection } from './hooks/useSelection'
import { useUploadFlow } from './hooks/useUploadFlow'
import { usePreview } from './hooks/usePreview'
import { useDrivePicker } from './hooks/useDrivePicker'
import { ellipsisPath } from '../../utils'
import styles from './index.module.css'

export default function DriveUploadMode() {
  // Source of truth for the scanned folder tree, and the root-picking state.
  const { root, tree, loading, error, pickRoot } = useFileTree()
  // Which files are checked in/out of the upload — independent of the
  // multi-selection below.
  const inclusion = useInclusion(tree)
  // The multi-selection of rows driving row highlighting and batch Drive
  // folder assignment.
  const selection = useSelection(tree)
  // Per-group/per-file Drive folder assignments.
  const assignments = useDriveAssignments()
  // Drives the Drive folder picker modal — single-row or batch — and applies
  // its result onto assignments.
  const picker = useDrivePicker(tree, selection, assignments)
  // Tracks the read-only lock and upload-modal state once Upload All is
  // clicked, and whether the tree is ready to upload.
  const uploadFlow = useUploadFlow(tree, inclusion, assignments)
  // Which file/page is shown in the right-hand preview panel.
  const preview = usePreview()

  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0

  // Groups start expanded; presence in this set (keyed by the group's full
  // path, e.g. "invoices/2026") means collapsed.
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
  const toggleGroup = (groupKey: string) => {
    setCollapsedGroups(prev => {
      const next = new Set(prev)
      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
      return next
    })
  }

  const handlePickRoot = async () => {
    if (await pickRoot()) uploadFlow.reset()
  }

  return (
    <Box className={styles.root}>
      <Toolbar>
        <Button size="xs" variant="default" onClick={handlePickRoot}>
          {root ? ellipsisPath(root) : 'Choose root folder…'}
        </Button>
        <Box className={styles.toolbarSpacer} />
        <Button size="xs" variant="default" disabled={uploadFlow.started || !tree} onClick={inclusion.selectAll}>
          Select All
        </Button>
        <Button size="xs" variant="default" disabled={uploadFlow.started || !tree} onClick={inclusion.selectNone}>
          Select None
        </Button>
        <Button size="xs" variant="default" disabled={uploadFlow.started || !tree || selection.size === 0} onClick={picker.pickSelection}>
          Assign Drive folder…
        </Button>
        <Tooltip
          label={tree ? 'Every selected file needs a Drive folder before uploading' : 'Choose a root folder first'}
          disabled={uploadFlow.started || uploadFlow.readyToUpload}
        >
          <span>
            <Button size="xs" disabled={uploadFlow.started || !uploadFlow.readyToUpload} onClick={uploadFlow.startUpload}>
              Upload All
            </Button>
          </span>
        </Tooltip>
      </Toolbar>

      <Box className={styles.body}>
        <ResizableLeftPanel
          left={
            <>
              <DriveFolderPickerModal
                opened={picker.opened}
                onClose={picker.close}
                onSelect={picker.apply}
              />
              {tree && (
                <UploadModal
                  opened={uploadFlow.uploadModalOpen}
                  tree={tree}
                  onClose={uploadFlow.closeUploadModal}
                />
              )}

              {loading && <Loader size="sm" />}
              {error && <Text size="sm" c="red">{error}</Text>}
              {!loading && !error && isEmpty && (
                <Text size="sm" c="dimmed">No files found under this folder.</Text>
              )}

              {tree && (
                <Stack gap="md">
                  {tree.subgroups.map(group => (
                    <GroupNode
                      key={group.name}
                      group={group}
                      collapsedGroups={collapsedGroups}
                      onToggle={toggleGroup}
                      assignments={assignments}
                      inheritedAssignment={null}
                      inclusion={inclusion}
                      selection={selection}
                      locked={uploadFlow.started}
                      onPick={picker.pickOne}
                      onPreviewFile={preview.setFile}
                    />
                  ))}
                  <FileList
                    files={tree.files}
                    assignments={assignments}
                    inheritedAssignment={null}
                    inclusion={inclusion}
                    selection={selection}
                    locked={uploadFlow.started}
                    onPick={picker.pickOne}
                    onPreviewFile={preview.setFile}
                  />
                </Stack>
              )}
            </>
          }
        >
          <DriveThumbnailPanel
            pdfPath={preview.file?.path ?? null}
            pageCount={preview.file?.pageCount ?? 0}
            selectedPage={preview.page}
            onSelectPage={preview.setPage}
          />

          <Box className={styles.detailColumn}>
            {preview.file && (
              <TruncatedText label={preview.file.name} size="sm" fw={600} className={styles.detailHeading}>
                {preview.file.name}
              </TruncatedText>
            )}
            {preview.file
              ? <DetailPanel pdfPath={preview.file.path} pageNum={preview.page} pageCount={preview.file.pageCount} />
              : <Box className={styles.emptyDetail} />}
          </Box>
        </ResizableLeftPanel>
      </Box>
    </Box>
  )
}

import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../../wailsjs/go/main/App'
import { filetree } from '../../../../wailsjs/go/models'
import { LocalFile, LocalFileGroup } from '../types'

// Flat, ordered list of every file in the tree (a group's own files, then
// its subgroups' files, recursively). Shared by the upload worker (order to
// process files in), the upload modal's per-group rollup counts, and the
// "every file in this group is done" check driving the Open-in-Drive link —
// one traversal so they can't drift out of sync on how they handle nesting.
export function flattenFiles(group: LocalFileGroup): LocalFile[] {
  return [...group.files, ...group.subgroups.flatMap(flattenFiles)]
}

// Assigns every group's lookup key in one pass, right after a scan, so no
// consumer needs its own tree walk to rebuild it. `key` mirrors the tree's
// own nesting (parent key + '/' + name), rooted at null for the scan root.
// `group` is the shape ScanLocalRoot actually returns, before `key` exists.
function withKeys(group: filetree.LocalFileGroup, key: string | null): LocalFileGroup {
  return {
    ...group,
    key,
    subgroups: group.subgroups.map(sub => withKeys(sub, key === null ? sub.name : `${key}/${sub.name}`)),
  }
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  // Resolves to whether a folder was actually picked (false if the user
  // cancelled the dialog), so callers know when a fresh root replaced the
  // previous one and any per-root state (e.g. the upload queue) should reset.
  pickRoot: () => Promise<boolean>
}

// Owns the currently scanned local folder: which root the user picked, the
// resulting file/subgroup tree, and loading/error state while ScanLocalRoot
// runs. The scan is an async Go RPC that can fail (bad permissions, folder
// moved/deleted mid-pick, etc.), so this state needs to live outside the
// tree itself — callers can show a spinner or an error message instead of
// rendering a stale or partial tree while a scan is in flight.
export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return false

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(withKeys(await ScanLocalRoot(folder), null))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
    return true
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState } from 'react'
import { flattenFiles } from './useFileTree'
import { resolveEffectiveAssignments, DriveAssignmentsHandle } from './useDriveAssignments'
import { InclusionHandle } from './useInclusion'
import { LocalFileGroup } from '../types'
import * as uploadQueue from '../uploadQueue'

export interface UploadFlowHandle {
  started: boolean
  uploadModalOpen: boolean
  readyToUpload: boolean
  startUpload: () => void
  closeUploadModal: () => void
  reset: () => void
}

// Once Upload All is clicked, the tree locks for the rest of this tree's
// session — the upload starts immediately, so there's no "in progress but
// not locked yet" window to account for. Retrying failed files happens
// inside the upload modal, not from here, so `started` never goes back to
// false except via reset (a fresh root pick).
export function useUploadFlow(tree: LocalFileGroup | null, inclusion: InclusionHandle, assignments: DriveAssignmentsHandle): UploadFlowHandle {
  const [uploadModalOpen, setUploadModalOpen] = useState(false)
  const [started, setStarted] = useState(false)

  const allFiles = tree ? flattenFiles(tree) : []
  const selectedFiles = allFiles.filter(f => inclusion.isFileSelected(f.path))
  const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
  const readyToUpload = selectedFiles.length > 0 && selectedFiles.every(f => effectiveAssignments!.get(f.path) != null)

  const startUpload = () => {
    if (!tree || !effectiveAssignments) return
    uploadQueue.start(selectedFiles.map(f => {
      const assignment = effectiveAssignments.get(f.path)
      // Upload All is disabled until readyToUpload is true, so every file
      // should resolve here — this is a defensive check against that
      // guard and this walk drifting out of sync, not an expected path.
      if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
      return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
    }))
    setStarted(true)
    setUploadModalOpen(true)
  }

  const closeUploadModal = () => setUploadModalOpen(false)

  // A new root discards the old tree's upload-queue state along with it —
  // picking a new root is the only way out of the read-only lock.
  const reset = () => {
    uploadQueue.reset()
    setStarted(false)
  }

  return { started, uploadModalOpen, readyToUpload, startUpload, closeUploadModal, reset }
}

import { ActionIcon, Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import TruncatedText from '../../TruncatedText'
import { flattenFiles } from '../hooks/useFileTree'
import * as uploadQueue from '../uploadQueue'
import { LocalFile, LocalFileGroup } from '../types'
import { OpenDriveFolder } from '../../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../../lib/globalErrorHandler'
import styles from './UploadModal.module.css'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Per-file status lives in the uploadQueue module singleton, not in this
// component's state — it re-renders by subscribing, the same pattern
// lib/pageCache's consumers use.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const paths = flattenFiles(tree).map(f => f.path)
  const settled = uploadQueue.hasSettled(paths)
  const canResume = settled && uploadQueue.hasPaused(paths)

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button
            variant="default"
            disabled={settled && !canResume}
            onClick={() => (canResume ? uploadQueue.resumePaused(paths) : uploadQueue.cancelAll())}
          >
            {canResume ? 'Resume' : 'Cancel'}
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group }: { group: LocalFileGroup }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" className={styles.groupCount}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" className={styles.fileName}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {(status === undefined || status === 'paused') && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'cancelled' && (
        <Group gap={8} wrap="nowrap">
          <Text size="sm" c="dimmed">Cancelled</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" className={styles.errorText}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {entry && (
        <ActionIcon
          variant="subtle"
          size="sm"
          aria-label={`Open destination Drive folder for ${file.name}`}
          onClick={() => OpenDriveFolder(entry.folderId).catch(handlePromiseRejection('Opening Drive folder failed'))}
        >
          <IconExternalLink size={14} />
        </ActionIcon>
      )}
    </Group>
  )
}

import { useEffect, useState } from 'react'
import { CancelUpload, UploadFile } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'

export type UploadStatus =
  /** Enqueued, waiting for the worker to reach it. */
  | 'queued'
  /** Was queued, then reverted here by cancelRemaining/cancelAll before the
   * worker reached it — never actually attempted. resumePaused re-queues
   * these in bulk. */
  | 'paused'
  /** The worker is currently awaiting UploadFile for it. */
  | 'uploading'
  /** Terminal: UploadFile resolved. */
  | 'done'
  /** Terminal: UploadFile rejected; .error holds the message. Retry re-queues it. */
  | 'error'
  /** Terminal: aborted mid-upload via cancel/cancelAll. Retry re-queues it. */
  | 'cancelled'

export interface UploadJob {
  path: string
  folderId: string
  name: string
}

export interface UploadEntry extends UploadJob {
  status: UploadStatus
  error?: string
}

// Per-file upload status, driven by a sequential (concurrency = 1) worker.
// A module-level singleton (like ../../lib/pageCache) rather than a hook:
// there is only ever one upload run in flight for the app, so the queue's
// lifetime doesn't need to be tied to any one component instance. Callers
// resolve each file's destination folder/name up front and pass in an
// ordered list of jobs — this module only knows how to run them one at a
// time and track status, not about the file tree or Drive assignments.
const filesByPath = new Map<string, UploadEntry>()
let pendingPaths: string[] = []
const listeners = new Set<() => void>()
let running = false
let cancelled = false

// Paths whose in-flight upload was cancelled. runQueue checks this once the
// awaited UploadFile call settles (success or failure) and, if present,
// leaves the status as 'cancelled' instead of overwriting it with
// 'done'/'error' — the request may have raced ahead of the abort signal, but
// the user's intent to cancel wins either way.
const cancelledInFlight = new Set<string>()

function notify() {
  for (const fn of listeners) fn()
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

export function useUploadQueueRender() {
  const [, setTick] = useState(0)
  useEffect(() => subscribe(() => setTick(t => t + 1)), [])
}

export function getStatus(path: string): UploadEntry | undefined {
  return filesByPath.get(path)
}

// True once none of the given files are still queued or uploading — i.e.
// each has either reached a terminal state (done/error) or was never
// started. Callers use this to know when it's safe to let the upload
// modal close.
export function hasSettled(paths: string[]): boolean {
  return !paths.some(path => {
    const status = filesByPath.get(path)?.status
    return status === 'queued' || status === 'uploading'
  })
}

// True if any of the given files are paused — i.e. there's a cancelled batch
// the modal can offer to resume.
export function hasPaused(paths: string[]): boolean {
  return paths.some(path => filesByPath.get(path)?.status === 'paused')
}

function updateStatus(path: string, status: UploadStatus, error?: string) {
  const existing = filesByPath.get(path)!
  filesByPath.set(path, { ...existing, status, error })
  notify()
}

async function runQueue() {
  if (running) return
  running = true
  while (!cancelled && pendingPaths.length > 0) {
    const path = pendingPaths.shift()!
    const job = filesByPath.get(path)!
    updateStatus(path, 'uploading')
    try {
      await UploadFile(job.path, job.folderId, job.name)
      if (!cancelledInFlight.delete(path)) updateStatus(path, 'done')
    } catch (e) {
      if (!cancelledInFlight.delete(path)) updateStatus(path, 'error', String(e))
    }
  }
  running = false
}

function enqueue(newJobs: UploadJob[]) {
  if (newJobs.length === 0) return
  cancelled = false
  for (const job of newJobs) {
    filesByPath.set(job.path, { ...job, status: 'queued', error: undefined })
    pendingPaths.push(job.path)
  }
  notify()
  void runQueue()
}

export function start(newJobs: UploadJob[]): void {
  enqueue(newJobs)
}

export function retry(job: UploadJob): void {
  enqueue([job])
}

// Stops starting new files; does not abort an in-flight request. Files
// still waiting their turn are marked paused since they were never attempted.
export function cancelRemaining(): void {
  cancelled = true
  for (const path of pendingPaths) updateStatus(path, 'paused')
  pendingPaths = []
}

// Aborts the file currently uploading. A no-op for any other status —
// queued files are handled by cancelRemaining, and done/error/cancelled are
// already settled. Marks the file 'cancelled' immediately rather than
// waiting on the CancelUpload round-trip or on however UploadFile's promise
// ends up settling.
export function cancel(path: string): void {
  if (filesByPath.get(path)?.status !== 'uploading') return
  cancelledInFlight.add(path)
  updateStatus(path, 'cancelled')
  CancelUpload(path).catch(handlePromiseRejection('Canceling upload failed'))
}

// The modal's single Cancel button: aborts whatever is currently uploading
// and pauses everything still queued. Concurrency is 1, so at most one entry
// can be 'uploading' at a time.
export function cancelAll(): void {
  cancelRemaining()
  for (const path of filesByPath.keys()) cancel(path)
}

// Re-queues every paused file among the given paths — i.e. resumes a batch
// left over from cancelAll. The file that was actually mid-upload when
// cancelled is left alone; it's 'cancelled', not 'paused', and already has
// its own per-row Retry button.
export function resumePaused(paths: string[]): void {
  const jobs = paths
    .map(path => filesByPath.get(path))
    .filter((entry): entry is UploadEntry => entry?.status === 'paused')
  enqueue(jobs)
}

export function reset(): void {
  if (!hasSettled(Array.from(filesByPath.keys()))) {
    // Callers must only invoke this once hasSettled() is true for all files;
    // otherwise a request from the discarded run could still be in flight and
    // would resurface after this call.
    throw new Error('reset() called while an upload is still in flight')
  }
  cancelled = false
  running = false
  cancelledInFlight.clear()
  filesByPath.clear()
  pendingPaths = []
  notify()
}

import { useRef } from 'react'
import { Badge, Box, Tooltip } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import { DriveAssignment } from '../types'
import { useIsTruncated } from '../../../lib/useIsTruncated'
import styles from './DriveAssignmentField.module.css'

interface Props {
  label: string
  assignment: DriveAssignment | null
  isOwn: boolean
  // True once the upload run has started for this tree — the destination is
  // fixed at that point (see uploadQueue's read-only rationale), so the
  // badge opens it in Drive instead of the picker, and the clear control
  // disappears. Picking a new root is the only way back to false.
  locked: boolean
  onPick: () => void
  onClear: () => void
  onOpen: () => void
}

// Pinned to the right of its row (filename or folder header) by the caller,
// so badges land at a consistent horizontal position regardless of nesting
// depth - scannable as a column rather than a per-row detail.
export default function DriveAssignmentField({ label, assignment, isOwn, locked, onPick, onClear, onOpen }: Props) {
  const textRef = useRef<HTMLSpanElement>(null)
  const displayPath = assignment ? assignment.path : 'Not assigned'
  const truncated = useIsTruncated(textRef, displayPath)

  const badge = (
    <Badge
      component="button"
      type="button"
      onClick={locked ? onOpen : onPick}
      aria-label={locked ? `Open Drive folder for ${label}` : `Set Drive folder for ${label}`}
      color={assignment ? 'blue' : 'gray'}
      variant={isOwn ? 'light' : 'outline'}
      size="sm"
      radius="sm"
      rightSection={locked ? <IconExternalLink size={10} /> : undefined}
      className={`${styles.badge} ${isOwn ? styles.badgeOwn : ''}`}
      styles={{ label: { overflow: 'hidden' } }}
    >
      <span ref={textRef} className={styles.badgeText}>
        📁 {displayPath}
      </span>
    </Badge>
  )

  return (
    <Box className={styles.container}>
      {truncated ? <Tooltip label={displayPath} openDelay={500}>{badge}</Tooltip> : badge}
      {isOwn && !locked && (
        <button
          type="button"
          onClick={onClear}
          aria-label={`Clear Drive folder for ${label}`}
          className={styles.clearButton}
        >
          ✕
        </button>
      )}
    </Box>
  )
}

