import { Button, ButtonProps } from '@mantine/core'
import { useAsyncAction } from '../lib/useAsyncAction'

interface Props extends ButtonProps {
  onClick: () => Promise<void>
  errorTitle?: string
  disabled?: boolean
}

// A Button whose onClick is an async action: disabled and showing a spinner
// for the duration of its own in-flight call, and reporting failure through
// the shared error-notification path. See useAsyncAction for the guard this
// builds on.
export default function AsyncButton({ onClick, errorTitle, disabled, ...buttonProps }: Props) {
  const action = useAsyncAction(onClick, errorTitle)

  return (
    <Button
      {...buttonProps}
      disabled={disabled || action.pending}
      loading={action.pending}
      onClick={() => action.run()}
    />
  )
}

import { ITEM_PADDING, HEADER_HEIGHT } from '../../constants'
import { PendingFocusHandle } from './usePendingFocus'
import ClippedPath from '../ClippedPath'
import { useAsyncAction } from '../../lib/useAsyncAction'
import styles from './OutputFileHeader.module.css'

interface Props {
  filename: string
  onChange: (name: string) => void
  firstPosition: number
  focus: PendingFocusHandle
  folder: string | null
  onPickFolder: () => Promise<void>
  isDuplicate: boolean
}

export default function OutputFileHeader({
  filename, onChange, firstPosition, focus, folder, onPickFolder, isDuplicate,
}: Props) {
  const pickFolder = useAsyncAction(onPickFolder, 'Failed to choose folder')
  const shouldFocus = focus.pendingFocus?.afterPosition === firstPosition - 1
  const cursorPos = focus.pendingFocus?.cursorPos ?? 0
  return (
    <div
      className={`${styles.header} ${isDuplicate ? styles.headerDuplicate : ''}`}
      style={{ margin: `4px ${ITEM_PADDING}px`, height: HEADER_HEIGHT - 8 }}
    >
      <div className={styles.nameRow}>
        <input
          ref={(el) => {
            if (el && shouldFocus) {
              el.focus()
              el.setSelectionRange(cursorPos, cursorPos)
              focus.clear()
            }
          }}
          type="text"
          value={filename}
          onChange={(e) => onChange(e.target.value)}
          placeholder="filename"
          className={`${styles.input} ${isDuplicate ? styles.inputDuplicate : ''}`}
        />
        <span className={styles.extension}>.pdf</span>
      </div>
      <ClippedPath path={folder} onClick={() => pickFolder.run()} disabled={pickFolder.pending} />
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { Box, Button, Divider, Group, Modal, Stack, Text, TextInput } from '@mantine/core'
import { notifications } from '@mantine/notifications'
import ThumbnailPanel from './ThumbnailPanel'
import DetailPanel from '../DetailPanel'
import Toolbar from '../Toolbar'
import AsyncButton from '../AsyncButton'
import { OpenFile, OpenPDF, PageCount, PickFolder, ExportSplit, CheckConflicts, DeleteFile } from '../../../wailsjs/go/main/App'
import { ellipsisPath } from '../../utils'
import { useOutputFiles } from './useOutputFiles'
import { usePendingFocus } from './usePendingFocus'
import { useAsyncAction } from '../../lib/useAsyncAction'
import * as pageCache from '../../lib/pageCache'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'
import styles from './index.module.css'

const DEFAULT_TEMPLATE = '{date} {name}'

function applyTemplate(template: string): { value: string; cursorPos: number } {
  const date = new Date().toISOString().split('T')[0]
  const withDate = template.replace('{date}', date)
  const nameIdx = withDate.indexOf('{name}')
  if (nameIdx === -1) return { value: withDate, cursorPos: withDate.length }
  return { value: withDate.replace('{name}', ''), cursorPos: nameIdx }
}

interface Props {
  initialPath?: string | null
}

export default function SplitMode({ initialPath }: Props) {
  const [pdfPath, setPdfPath] = useState<string | null>(null)
  const [pageCount, setPageCount] = useState(0)
  const [pageOrder, setPageOrder] = useState<number[]>([])
  const [selectedPage, setSelectedPage] = useState(1)
  const [outputFolder, setOutputFolder] = useState<string | null>(null)
  const [successModal, setSuccessModal] = useState<{show: boolean, outputPath: string, inputPath: string}>({show: false, outputPath: '', inputPath: ''})
  const outputFiles = useOutputFiles(outputFolder)
  const focus = usePendingFocus()
  const [template, setTemplate] = useState(DEFAULT_TEMPLATE)
  const [rotations, setRotations] = useState<Map<number, number>>(() => new Map())
  const [skipped, setSkipped] = useState<Set<number>>(() => new Set())

  useEffect(() => {
    return () => {
      if (pdfPath) pageCache.evict(pdfPath)
    }
  }, [pdfPath])

  const rotate = (page: number, delta: 90 | -90 = 90) => {
    setRotations(prev => {
      const next = new Map(prev)
      const deg = ((next.get(page) ?? 0) + delta + 360) % 360
      if (deg === 0) next.delete(page); else next.set(page, deg)
      return next
    })
  }

  const toggleSkip = (page: number) => {
    setSkipped(prev => {
      const next = new Set(prev)
      if (next.has(page)) next.delete(page); else next.add(page)
      return next
    })
  }

  const movePage = (fromPos: number, toPos: number) => {
    setPageOrder(prev => {
      const next = [...prev]
      const [page] = next.splice(fromPos, 1)
      next.splice(toPos, 0, page)
      return next
    })
  }

  const resetForFile = (count: number, path: string, tmpl: string) => {
    setPdfPath(path)
    setPageCount(count)
    setPageOrder(Array.from({ length: count }, (_, i) => i + 1))
    setSelectedPage(1)
    setRotations(new Map())
    setSkipped(new Set())
    outputFiles.reset(applyTemplate(tmpl).value)
    focus.clear()
  }

  useEffect(() => {
    if (!initialPath) return
    PageCount(initialPath)
      .then(count => resetForFile(count, initialPath, template))
      .catch(handlePromiseRejection('Failed to open file'))
  }, [initialPath])

  const handleOpen = async () => {
    const path = await OpenPDF()
    if (!path) return
    const count = await PageCount(path)
    resetForFile(count, path, template)
  }
  const openAction = useAsyncAction(handleOpen, 'Failed to open file')

  const handlePickOutputFolder = async () => {
    const folder = await PickFolder('Choose Output Folder')
    if (folder) setOutputFolder(folder)
  }

  const handleExport = async () => {
    if (!pdfPath || !outputFolder) return
    const sortedStarts = [...outputFiles.all.keys()].sort((a, b) => a - b)
    const files = sortedStarts.map((firstPos, i) => {
      const nextPos = sortedStarts[i + 1] ?? pageOrder.length
      const pages = pageOrder.slice(firstPos, nextPos).filter(p => !skipped.has(p))
      const f = outputFiles.all.get(firstPos)!
      return { pages, name: f.name, outDir: f.folderOverride ?? outputFolder! }
    })
    const conflicts = await CheckConflicts(files)
    if (conflicts.length > 0) {
      const names = conflicts.map(p => p.split('/').pop()).join(', ')
      notifications.show({ title: 'Filename conflict', message: `Already exists: ${names}`, color: 'orange', autoClose: false })
      return
    }
    await ExportSplit(pdfPath, files, Object.fromEntries(rotations))
    setSuccessModal({show: true, outputPath: outputFolder, inputPath: pdfPath})
  }

  const closeSuccessModal = () => setSuccessModal({show: false, outputPath: '', inputPath: ''})

  const handleDeleteInput = () => {
    const { inputPath } = successModal
    closeSuccessModal()
    setPdfPath(null)
    DeleteFile(inputPath).catch(handlePromiseRejection('Failed to delete file'))
  }


  const handleToggleSplitPoint = useCallback((afterPosition: number) => {
    const prefill = applyTemplate(template)
    const added = outputFiles.toggle(afterPosition, prefill.value)
    if (added) focus.request(afterPosition, prefill.cursorPos)
    else focus.clear()
  }, [template, outputFiles.toggle])

  return (
    <Box className={styles.root}>
      <Modal opened={successModal.show} onClose={closeSuccessModal} title="Export complete" centered>
        <Stack gap="md">
          <Group>
            <Text size="sm" c="dimmed" className={styles.outputPath}>{successModal.outputPath}</Text>
            <AsyncButton size="xs" variant="default" errorTitle="Failed to open folder" onClick={() => OpenFile(successModal.outputPath)}>
              Open in Finder
            </AsyncButton>
          </Group>
          <Divider />
          <div>
            <Text size="sm" mb={4}>What do you want to do with the input file?</Text>
            <Text size="sm" c="dimmed" mb="sm">{successModal.inputPath.split('/').pop()}</Text>
            <Group>
              <Button variant="default" onClick={closeSuccessModal}>Keep</Button>
              <Button color="red" onClick={handleDeleteInput}>Delete</Button>
            </Group>
          </div>
        </Stack>
      </Modal>
      <Toolbar>
        <Button size="xs" variant="default" disabled={openAction.pending} loading={openAction.pending} onClick={() => openAction.run()}>
          Open PDF
        </Button>
        <TextInput
          size="xs"
          placeholder={DEFAULT_TEMPLATE}
          value={template}
          onChange={(e) => setTemplate(e.currentTarget.value)}
          leftSection={<span className={styles.templateLabel}>Template</span>}
          leftSectionWidth={60}
          className={styles.templateInput}
        />
        <AsyncButton size="xs" variant="default" errorTitle="Failed to choose output folder" onClick={handlePickOutputFolder}>
          {outputFolder ? ellipsisPath(outputFolder) : 'Output folder…'}
        </AsyncButton>
        <AsyncButton
          size="xs"
          disabled={!pdfPath || !outputFolder || outputFiles.duplicateFirstPages.size > 0}
          errorTitle="Export failed"
          onClick={handleExport}
        >
          Export
        </AsyncButton>
      </Toolbar>

      <Box className={styles.body}>
        {pdfPath ? (
          <>
            <ThumbnailPanel
              pdfPath={pdfPath}
              pageOrder={pageOrder}
              selectedPage={selectedPage}
              onSelectPage={setSelectedPage}
              onToggleSplitPoint={handleToggleSplitPoint}
              outputFiles={outputFiles}
              outputFolder={outputFolder}
              focus={focus}
              rotations={rotations}
              onRotate={rotate}
              skipped={skipped}
              onToggleSkip={toggleSkip}
              onMovePage={movePage}
            />
            <DetailPanel
              pdfPath={pdfPath}
              pageNum={selectedPage}
              pageCount={pageCount}
              rotation={rotations.get(selectedPage) ?? 0}
              onRotate={(delta) => rotate(selectedPage, delta)}
            />
          </>
        ) : (
          <Box className={styles.emptyState}>
            <Button disabled={openAction.pending} loading={openAction.pending} onClick={() => openAction.run()}>Open PDF</Button>
          </Box>
        )}
      </Box>
    </Box>
  )
}

import { useRef } from 'react'
import { Badge, Box, Tooltip } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import { DriveAssignment } from '../types'
import { useIsTruncated } from '../../../lib/useIsTruncated'
import { useAsyncAction } from '../../../lib/useAsyncAction'
import styles from './DriveAssignmentField.module.css'

interface Props {
  label: string
  assignment: DriveAssignment | null
  isOwn: boolean
  // True once the upload run has started for this tree — the destination is
  // fixed at that point (see uploadQueue's read-only rationale), so the
  // badge opens it in Drive instead of the picker, and the clear control
  // disappears. Picking a new root is the only way back to false.
  locked: boolean
  onPick: () => void
  onClear: () => void
  onOpen: () => Promise<void>
}

// Pinned to the right of its row (filename or folder header) by the caller,
// so badges land at a consistent horizontal position regardless of nesting
// depth - scannable as a column rather than a per-row detail.
export default function DriveAssignmentField({ label, assignment, isOwn, locked, onPick, onClear, onOpen }: Props) {
  const textRef = useRef<HTMLSpanElement>(null)
  const displayPath = assignment ? assignment.path : 'Not assigned'
  const truncated = useIsTruncated(textRef, displayPath)
  const openAction = useAsyncAction(onOpen, 'Failed to open Drive folder')

  const badge = (
    <Badge
      component="button"
      type="button"
      onClick={locked ? () => openAction.run() : onPick}
      disabled={locked && openAction.pending}
      aria-label={locked ? `Open Drive folder for ${label}` : `Set Drive folder for ${label}`}
      color={assignment ? 'blue' : 'gray'}
      variant={isOwn ? 'light' : 'outline'}
      size="sm"
      radius="sm"
      rightSection={locked ? <IconExternalLink size={10} /> : undefined}
      className={`${styles.badge} ${isOwn ? styles.badgeOwn : ''}`}
      styles={{ label: { overflow: 'hidden' } }}
    >
      <span ref={textRef} className={styles.badgeText}>
        📁 {displayPath}
      </span>
    </Badge>
  )

  return (
    <Box className={styles.container}>
      {truncated ? <Tooltip label={displayPath} openDelay={500}>{badge}</Tooltip> : badge}
      {isOwn && !locked && (
        <button
          type="button"
          onClick={onClear}
          aria-label={`Clear Drive folder for ${label}`}
          className={styles.clearButton}
        >
          ✕
        </button>
      )}
    </Box>
  )
}

import { ActionIcon, Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import TruncatedText from '../../TruncatedText'
import { flattenFiles } from '../hooks/useFileTree'
import * as uploadQueue from '../uploadQueue'
import { LocalFile, LocalFileGroup } from '../types'
import { OpenDriveFolder } from '../../../../wailsjs/go/main/App'
import { useAsyncAction } from '../../../lib/useAsyncAction'
import styles from './UploadModal.module.css'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Per-file status lives in the uploadQueue module singleton, not in this
// component's state — it re-renders by subscribing, the same pattern
// lib/pageCache's consumers use.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const paths = flattenFiles(tree).map(f => f.path)
  const settled = uploadQueue.hasSettled(paths)
  const canResume = settled && uploadQueue.hasPaused(paths)

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button
            variant="default"
            disabled={settled && !canResume}
            onClick={() => (canResume ? uploadQueue.resumePaused(paths) : uploadQueue.cancelAll())}
          >
            {canResume ? 'Resume' : 'Cancel'}
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group }: { group: LocalFileGroup }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" className={styles.groupCount}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status
  const openFolder = useAsyncAction(
    () => OpenDriveFolder(entry!.folderId),
    'Opening Drive folder failed',
  )

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" className={styles.fileName}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {(status === undefined || status === 'paused') && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'cancelled' && (
        <Group gap={8} wrap="nowrap">
          <Text size="sm" c="dimmed">Cancelled</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" className={styles.errorText}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {entry && (
        <ActionIcon
          variant="subtle"
          size="sm"
          aria-label={`Open destination Drive folder for ${file.name}`}
          disabled={openFolder.pending}
          onClick={() => openFolder.run()}
        >
          <IconExternalLink size={14} />
        </ActionIcon>
      )}
    </Group>
  )
}
